VALUES ('d042a232-22be-4403-9a00-01dbb662a371', '00000000-0000-4000-8000-000000000400', 'Addis Ababa, 1963: We Must Unite or Perish https://youtu.be/-XAlNNcYxCc Between 22 and 25 May 1963, delegates from 32 African countries convened in the Ethiopian capital of Addis Ababa to establish the Organization for African Unity (OAU). The main objectives of the OAU were to rid the continent of the remaining vestiges of colonization and apartheid; to promote unity and solidarity amongst the African States; to coordinate and intensify cooperation for development; to safeguard the sovereignty and territorial integrity of member states and to promote international cooperation. History Grade 10 Student Textbook', 'G10-History-STB-2023-web.pdf p.1', '2026.1', 'published', '[0.002974864,0.01778859,-0.024774319,-0.015135027,0.021883177,0.012614683,-0.008801346,-0.0066451305,0.010132564,-0.091507606,-0.03488049,0.012343753,0.022164024,0.048378948,-0.0383768,-0.023083162,-0.021726303,-0.0007032958,0.0038958162,-0.020940965,0.035640042,0.029050734,0.0244527,-0.017975686,-0.033532657,-0.005777063,0.0240119,-0.045888018,-0.027327916,0.217469,-0.024587475,-0.021724941,0.027235992,0.01594417,0.019270873,0.009528753,-0.0015161239,-0.025325289,0.046808027,-0.030399373,0.010902195,-0.010683024,-0.021503072,0.03898731,-0.014778436,-0.0042315125,-0.019102171,0.030654304,0.028958553,-0.008823062,0.002066336,0.0025466094,0.01323121,-0.0343666,0.023570666,0.057102032,0.009002487,-0.0071920943,0.04295399,-0.0013206146,-0.0043996978,0.021430243,-0.037667565,0.06647953,-0.0047824485,0.008628237,0.0074717226,-0.07960252,0.007495537,0.010080189,0.01759781,-0.004756524,0.022539442,-0.018670043,-0.028091405,0.006334145,-0.0066702818,0.020120969,0.030528767,-0.003702309,0.01942832,0.010087063,-0.03858027,0.018557856,-0.028873146,-0.018231489,-0.008028364,-0.0056767873,0.045313854,-0.0043378114,-0.028653948,0.022923375,-0.024142113,-0.03853412,-0.015940601,-0.024389062,-0.033200245,-0.001701292,0.01912709