INSERT INTO curriculum_chunks (id, topic_id, content, source_ref, version, status, embedding, created_at, updated_at) 
VALUES ('d1d051dc-43ef-46df-9ebf-ee567f75ecb9', '00000000-0000-4000-8000-000000000400', 'The Upper House, called the House of Federation (HoF), is a representative body whose members are representatives of each “Nation, Nationality, and People”. Its main task is constitutional interpretation (Article 62). The constitution also recognized the establishment of an independent judiciary with the Federal Supreme Court at the top of a three-tier judicial hierarchy. Although the courts are free to decide overall justiciable cases including those in which constitutional rights of citizens stand tall, they have an equivocal position about the power to interpret the constitution as the ultimate interpretive power is explicitly given to the HoF. History Grade 10 Student Textbook The federal constitution makes contemporary Ethiopia a composite of nine states and two city administrations (Addis Ababa and Dire Dawa). The nine states thus established were 1.Tigray; 2.Afar; 3.Amhara; 4.Oromia; 5. Somali 6. Benishangul-Gumuz;; 7.Southern Nations Nationalities and Peoples’ State (SNNPRS); 8. Gambella; and 9. Harari . Although the states have an ethnic configuration, none of them is homogeneous. Some are even extremely heterogeneous. The SNNPRS, having around 56 different groups, is so diverse and complex that one is prompted to think of a form of “federation within a federation”. Benishangul/Gumuz and Gambella have 4-5 ethnic groups within their territory. Afar, Somali, and Oromia, which to many observers seem to be homogeneous, also have considerable numbers of and even pockets of non-Afar, non-Somali, and non-Oromo in their territory. Tigray, another state viewed as entirely homogeneous by many, is also a composite of the dominant Tigray, the Erob and the Kunama. The Amhara State has the Agaw, the Oromo and other minorities in addition to the dominant Amhara. The Harari State has a large number of Oromo inhabitants, there by necessitating the formation of a coalition government at the state level. In this way, Ethiopia’s constitution-makers have tried, or so they claimed, to forge a type of multi-ethnic federation. In terms of the size of the member states, Oromia State accounts for one-third of the country’s total landmass, whereas the Harari State is by far the smallest at only 340 square kilometers.', 'G10-History-STB-2023-web.pdf p.1', '2026.1', 'published', '[0.00869355,0.030457936,0.043404695,-0.06128484,0.001724097,-0.024672009,-0.024288973,-0.0324381,0.02637035,-0.09690433,-0.028002113,-0.005510655,0.03338646,0.009208803,-0.0573125,-0.055135496,0.024780098,-0.016399937,0.015059817,-0.010030742,0.03324161,0.029078465,0.05672941,-0.003382025,-0.0066711786,-0.012258948,0.02431119,-0.031043623,-0.029643232,0.17456463,-0.038034406,-0.008509181,0.013967034,0.007361453,0.0036233212,-0.038999807,-0.009749645,-0.035712093,0.042281207,-0.003606566,0.017487423,-0.0013659181,-0.006259995,0.033114105,-0.026565108,-0.0019801427,-0.01926862,0.001374122,0.000058614703,0.043268647,0.012589341,-0.020607691,0.012273282,-0.048825987,0.023016978,0.0035692812,0.014141375,0.020574505,0.026322324,0.0007569912,-0.011563933,0.036133055,-0.03366935,0.011971839,-0.010224706,-0.0065765553,0.047910694,-0.039765555,0.009980269,-0.0110746,-0.010470356,0.012424339,-0.024512812,-0.004969377,-0.015732847,-0.02660271,-0.05245342,-0.02465215,0.022358628,0.016441694,-0.003408129,0.04067404,-0.027433066,0.029565714,0.021544686,0.008447523,0.012154893,-0.058337297,-0.0037865506,-0.0119299665,-0.00015946123,0.006295002,-0.012616258,-0.039299227,-0.00032461743,-0.000510309,-0.025984611,-0.039779264,0.011304658,-0.022406988,-0.032835595,0.033974554,0.019018,0.0062486897,0.04365001,-0.004305929,-0.0056457664,0.021729968,0.0047988654,-0.024052903,-0.016384885,-0.30953133,-0.043662485,-0.01045979,-0.027138652,-0.046992738,-0.033346765,0.036252685,0.02458396,0.007945396,-0.0107524125,0.044045728,0.0040463987,-0.011676787,0.010379624,0.033758722,0.017180154,-0.028439486,0.019178195